/// <summary>
/// Logs a failed ABN validation web service call, including timeouts.
/// </summary>
internal final class METTelemetryABNValidationErrorEvent extends ISMTelemetryBase
{
    #define.MaxMessageLength(2000)

    private METABNValidationJobQueue abnValidationJobQueue;
    private int64                    durationMilliseconds;
    private str                      failureType;
    private str                      errorMessage;

}

Method.Source:
/// <summary>
/// Initializes the class <c>METTelemetryABNValidationErrorEvent</c>.
/// </summary>
/// <returns>Instance of <c>METTelemetryABNValidationErrorEvent</c>.</returns>
public static METTelemetryABNValidationErrorEvent construct()
{
    return new METTelemetryABNValidationErrorEvent();
}

/// <summary>
/// Runs the ABN validation error event.
/// </summary>
/// <param name = "_queue">Queue record being processed.</param>
/// <param name = "_failureType">Classification of the failure.</param>
/// <param name = "_errorMessage">Error details.</param>
/// <param name = "_durationMilliseconds">Elapsed time before the failure.</param>
public static void runTelemetryEvent(
    METABNValidationJobQueue _queue,
    str                      _failureType,
    str                      _errorMessage,
    int64                    _durationMilliseconds)
{
    METTelemetryABNValidationErrorEvent abnValidationErrorEvent = METTelemetryABNValidationErrorEvent::construct();

    abnValidationErrorEvent.initFromQueue(_queue, _durationMilliseconds);
    abnValidationErrorEvent.addRunTimePropertyToAppinsights(_failureType, _errorMessage);
    abnValidationErrorEvent.processEvent(METTelemetryEventNames::ABNValidationErrorEvent);
}

/// <summary>
/// Initializes the parameter setup values.
/// </summary>
/// <param name = "_parameterSetup">The parameter setup record to initialize.</param>
protected void initializeParameterSetup(ISMTelemetryParameterSetup _parameterSetup)
{
    _parameterSetup.TelemetryClass = this.telemetryName();
    _parameterSetup.IsEnabled      = NoYes::Yes;
    _parameterSetup.SeverityLevel  = ISMTelemetrySeverityLevel::Error;
}

/// <summary>
/// Determines whether the event should be logged.
/// </summary>
/// <returns>Always true; enablement is controlled by the parameter setup.</returns>
protected boolean shouldLogEvent()
{
    return true;
}

/// <summary>
/// No post population required.
/// </summary>
protected void postPopulateProperties()
{
}

/// <summary>
/// Stores the queue buffer that provides the telemetry context.
/// </summary>
/// <param name = "_queue">Queue record being processed.</param>
/// <param name = "_durationMilliseconds">Elapsed time of the web service call.</param>
private void initFromQueue(METABNValidationJobQueue _queue, int64 _durationMilliseconds)
{
    abnValidationJobQueue = _queue;
    durationMilliseconds  = _durationMilliseconds;
}

/// <summary>
/// Truncates free text so a long service payload cannot exceed the property limit.
/// </summary>
/// <param name = "_text">Text to truncate.</param>
/// <returns>Truncated text.</returns>
private str truncateText(str _text)
{
    return strLen(_text) > #MaxMessageLength
         ? subStr(_text, 1, #MaxMessageLength)
         : _text;
}

/// <summary>
/// Adds runtime telemetry properties to application insights.
/// </summary>
/// <param name = "_failureType">Classification of the failure.</param>
/// <param name = "_errorMessage">Error details.</param>
public void addRunTimePropertyToAppinsights(str _failureType, str _errorMessage)
{
    failureType  = _failureType;
    errorMessage = _errorMessage;

    this.addRuntimeProperty('customerNumber',       abnValidationJobQueue.CustAccount);
    this.addRuntimeProperty('abnNumber',            abnValidationJobQueue.ABN);
    this.addRuntimeProperty('outcome',              METABNValidationOutcomes::Failure);
    this.addRuntimeProperty('failureType',          failureType);
    this.addRuntimeProperty('isTimeout',            failureType == METABNValidationFailureTypes::Timeout ? 'true' : 'false');
    this.addRuntimeProperty('Message',              this.truncateText(errorMessage));
    this.addRuntimeProperty('referenceTable',       abnValidationJobQueue.RefTableId ? tableId2Name(abnValidationJobQueue.RefTableId) : '');
    this.addRuntimeProperty('referenceRecId',       int642Str(abnValidationJobQueue.RefRecId));
    this.addRuntimeProperty('processId',            guid2Str(abnValidationJobQueue.ProcessId));
    this.addRuntimeProperty('durationMilliseconds', int642Str(durationMilliseconds));
    this.addRuntimeProperty('legalEntity',          curExt());
}
